```python
# todo.py
import sys, json, os

TODO_FILE = "todos.json"

def load():
    if os.path.exists(TODO_FILE):
        return json.load(open(TODO_FILE, encoding="utf-8"))
    return []

def save(todos):
    json.dump(todos, open(TODO_FILE, "w", encoding="utf-8"), ensure_ascii=False, indent=2)

def add(text):
    todos = load()
    todos.append({"id": len(todos)+1, "text": text, "done": False})
    save(todos)
    print(f"已添加：{text}")

def show():
    for t in load():
        mark = "✓" if t["done"] else " "
        print(f'[{mark}] {t["id"]}. {t["text"]}')

def done(i):
    todos = load()
    if 0 < i <= len(todos):
        todos[i-1]["done"] = True
        save(todos)
        print(f"已完成：{todos[i-1]['text']}")

def rm(i):
    todos = load()
    if 0 < i <= len(todos):
        print(f"已删除：{todos.pop(i-1)['text']}")
        save(todos)

if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "show"
    if cmd == "add": add(" ".join(sys.argv[2:]))
    elif cmd == "show": show()
    elif cmd == "done": done(int(sys.argv[2]))
    elif cmd == "rm": rm(int(sys.argv[2]))
```

**项目结构**：单文件 `todo.py`，数据存 JSON。运行：`python todo.py add 买菜`、`python todo.py show`。

