package main

import "fmt"

func sum(nums []int, ch chan int) {
    total := 0
    for _, n := range nums {
        total += n
    }
    ch <- total  // 把结果发到 channel
}

func main() {
    ch := make(chan int)
    go sum([]int{1, 2, 3}, ch)
    result := <-ch  // 从 channel 接收
    fmt.Println(result)  // 6
}
