# ledger.py
import json, sys
from datetime import date

FILE = "ledger.json"

def load():
    try:
        return json.load(open(FILE, encoding="utf-8"))
    except FileNotFoundError:
        return []

def save(rows):
    json.dump(rows, open(FILE, "w", encoding="utf-8"), ensure_ascii=False, indent=2)

def add(kind, amount, note=""):
    rows = load()
    rows.append({"date": str(date.today()), "kind": kind, "amount": float(amount), "note": note})
    save(rows)
    print(f"已记录：{kind} {amount} {note}")

def report():
    rows = load()
    income = sum(r["amount"] for r in rows if r["kind"] == "收入")
    expense = sum(r["amount"] for r in rows if r["kind"] == "支出")
    print(f"总收入 {income}，总支出 {expense}，结余 {income - expense}")

if __name__ == "__main__":
    if sys.argv[1] == "add": add(sys.argv[2], sys.argv[3], " ".join(sys.argv[4:]))
    elif sys.argv[1] == "report": report()
