typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* push(Node* head, int v) {
    Node* n = malloc(sizeof(Node));
    n->data = v;
    n->next = head;
    return n;
}

void print(Node* head) {
    for (Node* p = head; p; p = p->next)
        printf("%d ", p->data);
    printf("\n");
}

int main() {
    Node* head = NULL;
    head = push(head, 1);
    head = push(head, 2);
    head = push(head, 3);
    print(head);  // 3 2 1
    return 0;
}
